{
  "name": "opencode-opper-budget",
  "version": "0.3.7",
  "description": "OpenCode CLI plugin that shows your Opper spend in the status bar",
  "type": "module",
  "license": "MIT",
  "author": "Mika Majakorpi",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/NitorCreations/opencode-opper-budget.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opper",
    "status-bar",
    "budget",
    "cli"
  ],
  "files": [
    "index.ts",
    "tui.tsx",
    "status.ts",
    "README.md"
  ],
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  }
}
